import { z as z2 } from "npm:zod@^3.25.76";
var search_products_default = defineTool2({
  name: "search_products",
  title: "Search products",
  description: "Full-text search over Tripplefour products by name, description, or category. Returns matching products in ZAR.",
  inputSchema: {
    query: z2.string().min(1).describe("Search text, e.g. 'vape', 'edible', 'cherry'."),
    limit: z2.number().int().min(1).max(50).optional().describe("Max results (default 10).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, limit }) => {
    const q = query.toLowerCase();
    const items = catalog.filter(
      (p) => p.name.toLowerCase().includes(q) || p.description.toLowerCase().includes(q) || p.category.toLowerCase().includes(q)
    ).slice(0, limit ?? 10).map((p) => ({
      id: p.id,
      name: p.name,
      category: p.category,
      price_zar: p.price,
      description: p.description,
      url: productUrl(p.id)
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { results: items, count: items.length }
    };
  }
});

// src/lib/mcp/tools/get-product.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z3 } from "npm:zod@^3.25.76";
var get_product_default = defineTool3({
  name: "get_product",
  title: "Get product",
  description: "Get full details for a single Tripplefour product by its ID.",
  inputSchema: {
    id: z3.string().min(1).describe("Product ID, e.g. 'acc-t444-cones'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const p = catalog.find((x) => x.id === id);
    if (!p) {
      return {
        content: [{ type: "text", text: `No product found with id '${id}'.` }],
        isError: true
      };
    }
    const item = {
      id: p.id,
      name: p.name,
      category: p.category,
      price_zar: p.price,
      description: p.description,
      coming_soon: p.comingSoon ?? false,
      url: productUrl(p.id)
    };
    return {
      content: [{ type: "text", text: JSON.stringify(item, null, 2) }],
      structuredContent: item
    };
  }
});

